let workspace='personal',page='Home',tabs=['Home'],drawerOpener=null,scheduleLayout='week';
const $=s=>document.querySelector(s),nav=$('#side-nav'),root=$('#page'),sidebar=$('.sidebar'),overlay=$('#overlay'),drawer=$('#drawer');
const header=(title,eyebrow,description,action='')=>`<header class="page-head"><div><p class="eyebrow">${eyebrow.toUpperCase()}</p><h1>${title}</h1><small>${description}</small></div>${action}</header>`;
function renderNav(){nav.innerHTML=navigation[workspace].map(([label,key])=>`<button type="button" data-page="${label}" class="${label===page?'active':''}" title="${label}" aria-current="${label===page?'page':'false'}">${icon(key)}<span class="nav-copy">${label}</span></button>`).join('');$('#workspace-label').textContent=workspace;document.querySelectorAll('[data-workspace]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.workspace===workspace)));}
function renderTabs(){$('#recent-tabs').innerHTML=tabs.map(label=>`<span class="tab ${label===page?'active':''}"><button type="button" data-tab="${label}">${label}</button>${tabs.length>1?`<button type="button" aria-label="Close ${label}" data-close="${label}">×</button>`:''}</span>`).join('');}
function home(){const modules=navigation.personal.slice(1).map(([label,key])=>`<button type="button" data-page="${label}"><span class="module-icon">${icon(key)}</span><span><strong>${label}</strong><small>${descriptions[label]}</small></span><span class="module-arrow">→</span></button>`).join('');return `${header('Home','Personal workspace','Items that need your attention, ordered by urgency.','<span class="role-chip">Student · Instructor</span>')}<section><div class="section-head"><h2>Needs attention</h2><span>${tasks.length} items</span></div><div class="task-list">${tasks.map(t=>`<button type="button" class="task" data-page="${t[4]}"><span class="signal ${t[3]}"></span><span class="task-copy"><strong>${t[0]}</strong><small>${t[1]}</small></span><span class="badge">${t[2]}</span><span>→</span></button>`).join('')}</div></section><section><div class="section-head"><h2>Workspace</h2><span>All enabled modules</span></div><div class="module-list">${modules}</div></section>`;}
function peoplePage(){return `${header('People',workspace==='personal'?'Personal workspace':workspace,'Manage student and instructor records.','<button class="row-action" type="button" data-add>Add person</button>')}<div class="toolbar"><input id="search" placeholder="Search people"><select><option>All roles</option><option>Student</option><option>Instructor</option></select><span class="count">${people.length} people</span></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Role</th><th>Email</th><th>Certificate</th><th>Status</th><th>Actions</th></tr></thead><tbody>${people.map((p,i)=>`<tr data-search="${Object.values(p).join(' ').toLowerCase()}"><td><strong>${p.name}</strong></td><td>${p.role}</td><td>${p.email}</td><td>${p.certificate}</td><td><span class="badge">${p.status}</span></td><td><button class="row-action" type="button" data-person="${i}">Open</button></td></tr>`).join('')}</tbody></table></div>`;}
function schedulePage(){const week=days.map(d=>`<section class="schedule-day ${d[0]==='Today'?'today':''}"><header><span>${d[0]}</span><strong>${d[1]}</strong><button type="button" data-lesson aria-label="Add lesson">+</button></header><div>${d[2].length?d[2].map(e=>`<button type="button" class="schedule-event ${e[3]}" data-lesson><time>${e[0]}</time><strong>${e[1]}</strong><small>${e[2]}</small></button>`).join(''):'<span class="schedule-empty">No lessons</span>'}</div></section>`).join('');const agenda=days.flatMap(d=>d[2].map(e=>`<tr><td><strong>${d[0]}, ${d[1]}</strong><small>${e[0]}</small></td><td>${e[1]}</td><td>${e[2]}</td><td><span class="badge">Scheduled</span></td><td><button class="row-action" data-lesson>Open</button></td></tr>`)).join('');return `${header('Schedule','Personal schedule','Plan lessons, review availability, and publish schedule changes.','<div class="head-actions"><button class="row-action">Review & publish</button><button class="primary compact-action" data-lesson>Add to schedule</button></div>')}<div class="schedule-controls"><div class="date-nav"><button>‹</button><strong>Oct 12–18, 2026</strong><button>›</button></div><div class="segments"><button data-schedule-view="list" aria-pressed="${scheduleLayout==='list'}">List</button><button data-schedule-view="week" aria-pressed="${scheduleLayout==='week'}">Week</button></div><button class="text-action">Today</button></div><div class="schedule-status"><span><i></i>Flight</span><span><i></i>Ground</span><span><i></i>Aircraft unavailable</span><span class="timezone">America/New_York</span></div>${scheduleLayout==='week'?`<div class="schedule-grid">${week}</div>`:`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Student</th><th>Lesson / Aircraft</th><th>Status</th><th>Actions</th></tr></thead><tbody>${agenda}</tbody></table></div>`}`;}
function dataPage(){const [description,cols,rows]=schemas[page]||schemas.Activity;return `${header(page,workspace,description,`<button class="primary compact-action">${page==='Account'?'Edit settings':page==='Organizations'?'Add organization':'Add record'}</button>`)}<div class="toolbar"><input id="search" placeholder="Search ${page.toLowerCase()}"><select><option>All statuses</option><option>Needs attention</option><option>Active</option></select><span class="count">${rows.length} records</span></div><div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}<th>Actions</th></tr></thead><tbody>${rows.map(row=>`<tr data-search="${row.join(' ').toLowerCase()}">${row.map((cell,i)=>`<td>${i===0?`<strong>${cell}</strong>`:i===3?`<span class="badge">${cell}</span>`:cell}</td>`).join('')}<td><button class="row-action">Open</button></td></tr>`).join('')}</tbody></table></div>`;}
function render(){root.innerHTML=page==='Home'?home():page==='People'?peoplePage():page==='Schedule'?schedulePage():dataPage();$('#crumb-workspace').textContent=workspace[0].toUpperCase()+workspace.slice(1);$('#crumb-page').textContent=page;$('#mobile-title').textContent=page;renderNav();renderTabs();}
function selectPage(next){page=next;if(!tabs.includes(next))tabs.push(next);render();sidebar.classList.remove('mobile-open');$('#mobile-menu').setAttribute('aria-expanded','false');}
function openDrawer(index,opener){const p=people[index]||{name:'',role:'Student',email:'',certificate:''};drawerOpener=opener;$('#drawer-title').textContent=index>=0?'Person details':page==='Schedule'?'Schedule item':'Add person';for(const [name,value] of Object.entries({name:p.name,role:p.role,email:p.email,certificate:p.certificate}))drawer.querySelector(`[name=${name}]`).value=value;drawer.hidden=false;overlay.hidden=false;$('#drawer-close').focus();}
function closeDrawer(){drawer.hidden=true;overlay.hidden=true;drawerOpener?.focus();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.workspace){workspace=b.dataset.workspace;page=navigation[workspace][0][0];tabs=[page];render();}else if(b.dataset.page)selectPage(b.dataset.page);else if(b.dataset.tab)selectPage(b.dataset.tab);else if(b.dataset.close){tabs=tabs.filter(t=>t!==b.dataset.close);if(page===b.dataset.close)page=tabs.at(-1)||navigation[workspace][0][0];render();}else if(b.hasAttribute('data-person'))openDrawer(Number(b.dataset.person),b);else if(b.hasAttribute('data-add')||b.hasAttribute('data-lesson'))openDrawer(-1,b);else if(b.dataset.scheduleView){scheduleLayout=b.dataset.scheduleView;render();}});
$('#collapse').addEventListener('click',()=>{const expanded=sidebar.dataset.expanded==='true';sidebar.dataset.expanded=String(!expanded);$('#collapse').innerHTML=`${icon(expanded?'expand':'collapse')}<span class="nav-copy">${expanded?'Expand':'Collapse'}</span>`;$('#collapse').title=expanded?'Expand navigation':'Collapse navigation';localStorage.setItem('pilotseal-demo-sidebar',expanded?'collapsed':'expanded');});
$('#mobile-menu').addEventListener('click',()=>{const open=sidebar.classList.toggle('mobile-open');$('#mobile-menu').setAttribute('aria-expanded',String(open));overlay.hidden=!open;});
overlay.addEventListener('click',()=>{if(!drawer.hidden)closeDrawer();sidebar.classList.remove('mobile-open');overlay.hidden=true;});$('#drawer-close').addEventListener('click',closeDrawer);$('#drawer-cancel').addEventListener('click',closeDrawer);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!drawer.hidden)closeDrawer();});
$('#drawer-form').addEventListener('submit',e=>{e.preventDefault();closeDrawer();const note=document.createElement('p');note.className='toast';note.textContent='Demo change applied for this session.';root.prepend(note);});
document.addEventListener('input',e=>{if(e.target.id==='search'){const q=e.target.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.dataset.search.includes(q));}});
const collapsed=localStorage.getItem('pilotseal-demo-sidebar')==='collapsed';sidebar.dataset.expanded=String(!collapsed);$('#collapse').innerHTML=`${icon(collapsed?'expand':'collapse')}<span class="nav-copy">${collapsed?'Expand':'Collapse'}</span>`;$('#collapse').title=collapsed?'Expand navigation':'Collapse navigation';render();
